import{_ as s,o as i,c as a,a2 as d}from"./chunks/framework.C-si7TFR.js";const k=JSON.parse('{"title":"Rsyslog 触发器","description":"通过 TCP 或 UDP 接收 syslog 消息来触发工作流。支持按 facility、severity 和正则表达式进行过滤。","frontmatter":{"title":"Rsyslog 触发器","description":"通过 TCP 或 UDP 接收 syslog 消息来触发工作流。支持按 facility、severity 和正则表达式进行过滤。","meta":[{"name":"keywords","content":"Rsyslog, Syslog, 触发器, TCP, UDP, 日志监控, Facility, Severity, 正则过滤, 低代码, AI工作流, 流程引擎"}]},"headers":[],"relativePath":"zh/trigger_rsyslog.md","filePath":"zh/trigger_rsyslog.md"}'),e={name:"zh/trigger_rsyslog.md"};function r(l,t,o,n,h,p){return i(),a("div",null,[...t[0]||(t[0]=[d(`<h2 id="rsyslog-触发器" tabindex="-1">Rsyslog 触发器 <a class="header-anchor" href="#rsyslog-触发器" aria-label="Permalink to &quot;Rsyslog 触发器&quot;">​</a></h2><p>通过 TCP 或 UDP 协议监听 syslog 消息来触发工作流。当收到匹配的 syslog 消息时，工作流会自动执行。适用于实时日志监控、告警和自动化事件响应场景。</p><p>支持按 <strong>facility</strong>（设施）、<strong>severity</strong>（严重级别）和<strong>正则表达式</strong>对消息进行过滤，确保只有相关的日志事件才会触发工作流。</p><h2 id="入参" tabindex="-1">入参 <a class="header-anchor" href="#入参" aria-label="Permalink to &quot;入参&quot;">​</a></h2><ul><li><p><strong>Protocol</strong>（必填）：监听的网络协议，支持 <code>tcp</code> 和 <code>udp</code>。</p></li><li><p><strong>Listen Port</strong>（必填）：监听端口号（1–65535）。</p></li><li><p><strong>Listen Host</strong>：绑定的 IP 地址，默认为 <code>127.0.0.1</code>（仅本地）。设置为 <code>0.0.0.0</code> 可监听所有网络接口。</p></li><li><p><strong>Facility Filter</strong>：逗号分隔的 facility 名称列表，仅接受匹配的消息。为空则接受所有 facility。可用值：</p><table tabindex="0"><thead><tr><th>编码</th><th>名称</th><th>编码</th><th>名称</th></tr></thead><tbody><tr><td>0</td><td>kern</td><td>12</td><td>ntp</td></tr><tr><td>1</td><td>user</td><td>13</td><td>log-audit</td></tr><tr><td>2</td><td>mail</td><td>14</td><td>log-alert</td></tr><tr><td>3</td><td>daemon</td><td>15</td><td>clock-daemon</td></tr><tr><td>4</td><td>auth</td><td>16</td><td>local0</td></tr><tr><td>5</td><td>syslog</td><td>17</td><td>local1</td></tr><tr><td>6</td><td>lpr</td><td>18</td><td>local2</td></tr><tr><td>7</td><td>news</td><td>19</td><td>local3</td></tr><tr><td>8</td><td>uucp</td><td>20</td><td>local4</td></tr><tr><td>9</td><td>cron</td><td>21</td><td>local5</td></tr><tr><td>10</td><td>authpriv</td><td>22</td><td>local6</td></tr><tr><td>11</td><td>ftp</td><td>23</td><td>local7</td></tr></tbody></table><p>示例：<code>kern,daemon,local0</code></p></li><li><p><strong>Severity Filter</strong>：逗号分隔的 severity 名称列表，仅接受匹配的消息。为空则接受所有 severity。可用值（从最严重到最轻微）：</p><table tabindex="0"><thead><tr><th>编码</th><th>名称</th><th>说明</th></tr></thead><tbody><tr><td>0</td><td>emerg</td><td>紧急</td></tr><tr><td>1</td><td>alert</td><td>警报</td></tr><tr><td>2</td><td>crit</td><td>严重</td></tr><tr><td>3</td><td>err</td><td>错误</td></tr><tr><td>4</td><td>warning</td><td>警告</td></tr><tr><td>5</td><td>notice</td><td>通知</td></tr><tr><td>6</td><td>info</td><td>信息</td></tr><tr><td>7</td><td>debug</td><td>调试</td></tr></tbody></table><p>示例：<code>emerg,alert,crit,err</code></p></li><li><p><strong>Pattern Filter</strong>：正则表达式过滤条件。仅当消息的 <code>message</code> 或 <code>raw_message</code> 字段匹配该正则时才会触发工作流。为空则不做正则过滤。</p><p>示例：<code>error|failed|timeout</code></p></li></ul><h2 id="出参" tabindex="-1">出参 <a class="header-anchor" href="#出参" aria-label="Permalink to &quot;出参&quot;">​</a></h2><p>每次收到匹配的 syslog 消息时，工作流将被触发，输出数据如下：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;facility&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;daemon&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;severity&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;err&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;timestamp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Jan 14 10:30:00&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;hostname&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;web-server-01&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;program&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sshd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Failed password for root from 192.168.1.100 port 22 ssh2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;raw_message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;27&gt;Jan 14 10:30:00 web-server-01 sshd[1234]: Failed password for root from 192.168.1.100 port 22 ssh2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;source_ip&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;192.168.1.50:514&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>facility</td><td>syslog 设施名称（如 kern、daemon）</td></tr><tr><td>severity</td><td>syslog 严重级别（如 err、warning）</td></tr><tr><td>timestamp</td><td>syslog 消息中的时间戳</td></tr><tr><td>hostname</td><td>发送消息的主机名</td></tr><tr><td>program</td><td>产生消息的程序名</td></tr><tr><td>message</td><td>解析后的日志消息内容</td></tr><tr><td>raw_message</td><td>原始 syslog 消息</td></tr><tr><td>source_ip</td><td>发送方的 IP 地址和端口</td></tr></tbody></table><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><ol><li>当工作流启用时，IOLinker 会在配置的地址和端口上启动 TCP 或 UDP 监听器。</li><li>配置您的 rsyslog（或其他兼容 syslog 的服务）将日志转发到此监听地址。</li><li>收到的 syslog 消息会被自动解析（支持 RFC 3164 BSD 格式和 RFC 5424 格式）。</li><li>根据配置的 facility、severity 和正则过滤条件对消息进行过滤。</li><li>匹配的消息将触发工作流执行，解析后的 syslog 数据作为工作流输入。</li></ol><h3 id="rsyslog-配置示例" tabindex="-1">rsyslog 配置示例 <a class="header-anchor" href="#rsyslog-配置示例" aria-label="Permalink to &quot;rsyslog 配置示例&quot;">​</a></h3><p>在 <code>/etc/rsyslog.conf</code> 或 <code>/etc/rsyslog.d/</code> 目录下的配置文件中添加：</p><p><strong>UDP 转发：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*.* @127.0.0.1:514</span></span></code></pre></div><p><strong>TCP 转发：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*.* @@127.0.0.1:514</span></span></code></pre></div>`,17)])])}const c=s(e,[["render",r]]);export{k as __pageData,c as default};
